pub fn p95(samples: &[u64]) -> Option<u64> {
if samples.is_empty() { return None; } let mut sorted=samples.to_vec(); sorted.sort_unstable(); let n=sorted.len(); let rank=n-n/20; Some(sorted[rank-1])
}

}
