                    .bytes()
                    .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
            {
                request_id = value;
            }
            if name.eq_ignore_ascii_case("content-type") {
                content_type = Some(value);
            }
            if name.eq_ignore_ascii_case("idempotency-key") {
                key = Some(value);
            }
        }
